// Example: pseudo watermark generator
function watermark(text, tenantId, key) {
  // deterministic stamp from tenant-specific material
  const seed = tenantId + ':' + key;
  const stamp = crypto.createHash('sha256').update(seed).digest('hex');

  // embed at token level with minimal latency
  return embedWatermarkTokens(text, stamp);
}
```

